const $=(s,r=document)=>r.querySelector(s);
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',book:'M12 6c-3-3-8-3-10-2v15c3-1 7-1 10 2m0-15c3-3 8-3 10-2v15c-3-1-7-1-10 2V6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',review:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2',chart:'M4 20V10m8 10V4m8 16v-7M2 22h20',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 2h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1 1-3',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',pen:'m16 3 5 5-13 13H3v-5L16 3M13 6l5 5',cards:'M7 3h14v16H7zM3 7v14h14',sound:'M11 4 5 9H2v6h3l6 5V4M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',text:'M4 5h16M12 5v15M8 20h8',flame:'M12 2c0 6-6 6-6 12a6 6 0 0 0 12 0c0-3-1-5-3-7 0 4-3 5-3 5 2-5 0-10 0-10',calendar:'M4 5h16v16H4zM4 10h16M8 2v5m8-5v5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',leaf:'M21 3C6 1 0 11 6 18c7 7 17 1 15-15ZM3 21 16 8',download:'M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4',upload:'M12 16V4m-5 5 5-5 5 5M3 17v4h18v-4',menu:'M3 6h18M3 12h18M3 18h18',play:'m8 4 12 8-12 8V4',target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 5a5 5 0 1 0 0 10 5 5 0 0 0 0-10m0 4v2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l4 3',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m-3 6c0-4 7-4 6 0-1 2-3 1-3 4m0 3v1',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const jp=s=>`<span lang="ja">${esc(s)}</span>`;
const mainMeaning=k=>(k.meanings?.[0]||'').split(/;|,/)[0];
const itemReading=k=>k.reading||k.on?.[0]||k.kun?.[0]?.replace(/[.-]/g,'')||k.char;
const shuffle=a=>[...a].sort(()=>Math.random()-.5);
const modeNames={guided:'Guided lesson',flash:'Flashcards',write:'Writing practice',listen:'Listening',context:'Sentence practice'};
let data={},items=new Map(),courses=[],state={view:'home',tab:'kanji',search:'',filter:'all',page:0},session=null,writer=null,animToken=0,voices=[],installPrompt=null,storageOK=true;
const KEY='kanji-path-v1';
const freshProfile=name=>({id:crypto.randomUUID(),name,cards:{},history:[],tests:[],attempts:[],mistakes:{},goal:10,created:Date.now()});
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null')}catch{saved=null;storageOK=false}
if(!saved||!Array.isArray(saved.profiles)||!saved.profiles.length)saved={version:1,profiles:[freshProfile('Learner')],active:null,lenient:true,speed:0.8,voice:''};
if(!saved.profiles.some(p=>p.id===saved.active))saved.active=saved.profiles[0].id;
const profile=()=>saved.profiles.find(p=>p.id===saved.active)||saved.profiles[0];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));storageOK=true}catch{storageOK=false;toast('Progress could not be saved. Export a backup in Settings.')}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(html){stopSpeech();animToken++;writer=null;const d=$('#modal');d.innerHTML=html;if(!d.open)d.showModal();document.body.classList.add('modal-open');d.scrollTop=0}
function closeModal(){resumeSession();stopSpeech();animToken++;writer=null;session=null;$('#modal').close();document.body.classList.remove('modal-open');render()}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();if(session){exitSession()}else closeModal()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&!session)closeModal()});
function head(title,subtitle=''){return `<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="close" data-action="${session?'exit-session':'close'}" aria-label="Close">${icon('close')}</button></div>`}
function nav(view){
  const next=resolveRoute(view);
  if(state.view==='test'&&next!=='test')tests.stopAudio();
  state.view=next;location.hash=next;render();
  window.scrollTo({top:0,behavior:'instant'});
  document.querySelector('.page-heading h1')?.focus({preventScroll:true});
}
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v!==state.view)nav(v)});
const dueCards=()=>availableReviews(profile().cards,items,data.strokes);
const todayHistory=()=>[...profile().history,...(profile().attempts||[]).filter(a=>a.origin!=='practice')].filter(h=>localDay(h.at)===localDay());
const learnedIds=()=>new Set(Object.entries(profile().cards).filter(([,v])=>v.reps>0).map(([key])=>key.split(':').slice(1).join(':')));
function streak(){const days=new Set([...profile().history,...(profile().attempts||[]).filter(a=>a.origin!=='practice')].map(h=>localDay(h.at)));let n=0;const d=new Date();if(!days.has(localDay(d)))d.setDate(d.getDate()-1);while(days.has(localDay(d))){n++;d.setDate(d.getDate()-1)}return n}
function mastered(){return new Set(Object.entries(profile().cards).filter(([,c])=>c.interval>=21&&c.reps>=3).map(([k])=>k.split(':').slice(1).join(':')))}
const courseProgress=c=>{const learned=learnedIds();return Math.round(c.items.filter(k=>learned.has(k.id)).length/Math.max(1,c.items.length)*100)};
function makeCourses(){const byChars=s=>Array.from(s).map(c=>items.get(c)).filter(Boolean);courses=[
 {id:'first',title:'First 15 kanji',subtitle:'Start with numbers and simple shapes.',symbol:'一',label:'BEGIN HERE',items:byChars('一二三四五六七八九十人日月山川'),level:'15 essential kanji'},
 {id:'hiragana',title:'Hiragana',subtitle:'The sounds at the heart of Japanese.',symbol:'あ',label:'FOUNDATIONS',items:data.kana.filter(k=>k.kind==='hiragana'),level:'46 characters'},
 {id:'katakana',title:'Katakana',subtitle:'Read names, loanwords, and more.',symbol:'ア',label:'FOUNDATIONS',items:data.kana.filter(k=>k.kind==='katakana'),level:'46 characters'},
 ...[5,4,3,2,1].map(n=>({id:'n'+n,title:`N${n} kanji`,subtitle:{5:'Begin with familiar characters for everyday Japanese.',4:'Build on the basics with common everyday kanji.',3:'Expand your reading with intermediate kanji.',2:'Read more detailed texts and abstract ideas.',1:'Explore advanced kanji for complex reading.'}[n],symbol:{5:'日',4:'学',3:'旅',2:'識',1:'響'}[n],label:'JLPT KANJI',items:data.kanji.filter(k=>k.jlpt===n),level:`Estimated JLPT N${n} · kanji collection`})),
 ...[1,2,3,4,5,6,8].map(g=>({id:'grade'+g,title:g===8?'Secondary-school kanji':`School grade ${g}`,subtitle:g===8?'Continue with secondary-school kanji.':'Explore the kanji taught in Japanese schools.',symbol:['','木','学','世','旅','豊','夢','','道'][g],label:g===8?'ADVANCED':'KANJI COLLECTION',items:data.kanji.filter(k=>k.grade===g),level:g===8?'Secondary school':`Japanese school grade ${g}`})),
 {id:'vocab',title:'Beginner vocabulary',subtitle:'Your original beginner words, grouped by topic.',symbol:'語',label:'VOCABULARY',items:filterVocabulary(data.vocab,'core'),level:'127 beginner words'},
 ...[5,4,3,2,1].map(n=>({id:'vocab-n'+n,title:`N${n} vocabulary`,subtitle:{5:'Start with familiar words and everyday expressions.',4:'Build on the basics for daily conversations.',3:'Expand your reading and everyday understanding.',2:'Explore more detailed and abstract language.',1:'Study advanced words for complex reading and conversation.'}[n],symbol:'語',label:'JLPT VOCABULARY',items:filterVocabulary(data.vocab,'n'+n),level:`Estimated JLPT N${n} · independent word collection`})),
 {id:'sentences',title:'Beginner sentences',subtitle:'Complete sentences and hear them spoken.',symbol:'文',label:'READ & LISTEN',items:data.sentences,level:'40 beginner sentences'}];}
function render(){
  if(!data.kanji)return;
  $('#app').innerHTML=shellHTML({view:state.view,learner:profile(),due:dueCards().length,streak:streak(),online:navigator.onLine,storageOK,content:views[state.view](),esc,icon});
  if(state.view==='library')renderLibraryResults();
}
function pageHeading(title,description,extra=''){return `<div class="page-heading"><div><h1 tabindex="-1">${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${extra}</div>`}
function statsHTML(){
  const learned=learnedIds(),known=data.kanji.filter(k=>learned.has(k.id)).length,today=todayHistory().length;
  return `<div class="stats">${[['Kanji studied',known,`of ${data.kanji.length.toLocaleString()}`],['Reviews due',dueCards().length,'ready now'],['Today',today,`of ${profile().goal} activities`],['Streak',streak(),'days']].map(([label,num,note])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-number"><b>${num}</b><span>${note}</span></div></div>`).join('')}</div>`;
}
function courseRow(c){
  const progress=courseProgress(c),level=/^n[1-5]$/.test(c.id)?c.id.toUpperCase():c.id.startsWith('vocab-n')?c.id.slice(-2).toUpperCase():c.symbol;
  return `<button class="course-row" data-course="${esc(c.id)}"><span class="course-symbol" lang="ja">${esc(level)}</span><span class="course-copy"><h3>${esc(c.title)}</h3><p>${c.items.length.toLocaleString()} ${c.id.includes('kana')?'characters':'items'} · ${progress}% studied</p></span><span class="course-progress" aria-hidden="true">${progress}%<span class="stat-line"><i style="width:${progress}%"></i></span></span>${icon('chevron')}</button>`;
}
function modesHTML(){return `<div class="modes">${[['write','pen','Writing','Stroke order and handwriting'],['flash','cards','Flashcards','Readings and meanings'],['listen','sound','Listening','Listen and choose'],['context','text','Sentence practice','Complete the missing word']].map(([mode,glyph,title,description])=>`<button class="mode-card" data-practice="${mode}"><span class="mode-icon">${icon(glyph)}</span><span><h3>${title}</h3><p>${description}</p></span>${icon('chevron')}</button>`).join('')}</div>`}
function homeView(){
  const today=todayHistory().length,goal=profile().goal,due=dueCards().length,known=learnedIds();
  const first=['hiragana','katakana','first'].map(id=>courses.find(c=>c.id===id));
  const next=[courses.find(c=>c.id==='first'),...first.slice(0,2),...courses.filter(c=>/^n[1-5]$/.test(c.id))].find(c=>courseProgress(c)<100)||courses.find(c=>c.id==='n5');
  const featured=data.kanji.find(k=>k.jlpt===5&&!known.has(k.id))||items.get('学');
  const reading=[featured.on?.[0],featured.kun?.[0]?.replace(/[.-]/g,'')].filter(Boolean).join(' · ');
  return `${pageHeading('Study',`${profile().name} · ${new Date().toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric'})}`)}
    <div class="ref-home-grid"><div class="ref-home-main"><section class="ref-study-entry" aria-labelledby="study-entry-title"><p class="ref-label">Your space. Your next step.</p><h2 id="study-entry-title">What will you study today?</h2><p>A short session of familiar reviews, useful forms, listening, and reading.</p><p class="small muted">${due?`${due} reviews are ready when you are.`:'Your next lesson is ready.'}${voices.length?'':' Listening joins your mixed session when a Japanese voice is available.'}</p><div class="button-row"><button class="primary" data-daily-mixed="true">Start mixed session ${icon('arrow')}</button>${due?`<button class="secondary" data-action="start-review">Review ${due} ${icon('review')}</button>`:''}</div></section>
    <section class="ref-next-step"><p class="ref-label">Pick up where you left off</p><h2>${esc(next.title)}</h2><p>${next.items.length.toLocaleString()} items · ${courseProgress(next)}% studied</p><div class="button-row"><button class="secondary" data-start-course="${esc(next.id)}">${courseProgress(next)?'Continue collection':'Start a lesson'} ${icon('arrow')}</button><button class="text-link" data-nav="learn">Browse collections ${icon('chevron')}</button></div></section></div>
    <section class="ref-desk" aria-labelledby="study-desk-title"><div class="ref-desk-top"><div><p class="ref-label">Your study desk</p><h2 id="study-desk-title">One character at a time</h2></div><span class="tag">Est. N${featured.jlpt}</span></div><button class="ref-character" data-detail="${esc(featured.id)}" aria-label="Explore ${esc(featured.char)}: ${esc(mainMeaning(featured))}"><span class="ref-character-glyph" lang="ja">${esc(featured.char)}</span><span class="ref-character-reading" lang="ja">${esc(reading)}</span><span class="ref-character-meaning">${esc(mainMeaning(featured))}</span></button>
    <section class="daily-progress" aria-label="Today’s progress"><div class="daily-progress-top"><strong>Today’s progress</strong><span>${today} / ${goal} activities</span></div><progress value="${Math.min(today,goal)}" max="${goal}" aria-label="Daily practice goal">${today} of ${goal}</progress><p>${today>=goal?'Daily goal reached.':`${goal-today} more ${goal-today===1?'activity':'activities'} to reach your goal.`}</p></section><div class="ref-home-counters"><span><b>${streak()}</b> day streak</span><span><b>${due}</b> reviews due</span><span>Saved on this device</span></div></section></div>
    <section><div class="section-title"><div><h2>Learning path</h2><p>Start with the foundations, then work through N5–N1.</p></div><button class="text-link" data-nav="learn">View all ${icon('chevron')}</button></div><div class="course-list">${first.map(courseRow).join('')}</div></section>
    <section class="collection-section"><div class="section-title"><div><h2>Practice your way</h2><p>Choose a skill and collection.</p></div></div>${modesHTML()}</section>
    <section class="more-list"><button class="more-row" data-nav="test">${icon('target')}<span><strong>Test yourself</strong><small>Knowledge, conjugation, reading, and dictation.</small></span>${icon('chevron')}</button></section>`;
}
function learnView(){
  const group=(title,description,list)=>`<section class="collection-section"><div class="section-title"><div><h2>${title}</h2><p>${description}</p></div></div><div class="collection-list">${list.map(courseRow).join('')}</div></section>`;
  const grammarRows=[5,4,3,2,1].map(n=>{
    const list=data.grammar.filter(g=>g.jlpt===n),count=list.filter(g=>profile().cards['flash:'+g.id]?.reviews).length,percent=Math.round(count/list.length*100);
    return `<button class="course-row" data-grammar-level="${n}"><span class="course-symbol">N${n}</span><span class="course-copy"><h3>N${n} grammar</h3><p>${list.length} lessons · ${count} studied</p></span><span class="course-progress" aria-hidden="true">${percent}%<span class="stat-line"><i style="width:${percent}%"></i></span></span>${icon('chevron')}</button>`;
  }).join('');
  return `${pageHeading('Learning path','Choose a collection. All learning material is included.')}<p class="small muted">Suggested order: hiragana, katakana, first kanji, then N5 kanji and vocabulary. JLPT levels are unofficial study estimates.</p>
    ${group('Foundations','Basic kana and the first 15 kanji.',courses.filter(c=>['hiragana','katakana','first'].includes(c.id)).sort((a,b)=>['hiragana','katakana','first'].indexOf(a.id)-['hiragana','katakana','first'].indexOf(b.id)))}
    ${group('Kanji · N5–N1','Meanings, readings, writing, and listening.',courses.filter(c=>/^n[1-5]$/.test(c.id)))}
    ${group('Vocabulary · N5–N1','Readings, meanings, and sentence examples.',courses.filter(c=>c.id.startsWith('vocab-n')))}
    <section class="collection-section"><div class="section-title"><div><h2>Grammar · N5–N1</h2><p>Formation rules, examples, and recall practice.</p></div></div><div class="collection-list">${grammarRows}</div></section>
    ${group('School-grade kanji','All kanji by Japanese school grade, including ungraded JLPT items.',courses.filter(c=>c.id.startsWith('grade')))}
    ${group('Beginner vocabulary & sentences','Topic vocabulary and sentence-gap practice.',courses.filter(c=>['vocab','sentences'].includes(c.id)))}`;
}
function libraryView(){return `${pageHeading('Library','Search kanji, kana, vocabulary, and sentences.')}<div class="tabs" role="tablist">${[['kanji',`Kanji · ${data.kanji.length.toLocaleString()}`],['hiragana','Hiragana'],['katakana','Katakana'],['vocab',`Vocabulary · ${data.vocab.length.toLocaleString()}`],['sentences',`Sentences · ${data.sentences.length}`]].map(([id,t])=>`<button role="tab" aria-selected="${state.tab===id}" data-tab="${id}" class="${state.tab===id?'active':''}">${t}</button>`).join('')}</div>${libraryLevelsHTML()}<div class="toolbar"><div class="searchbox">${icon('search')}<input id="library-search" placeholder="Search a word, reading, romaji, or meaning…" aria-label="Search library" value="${esc(state.search)}"></div><select id="library-filter" aria-label="Filter collection">${filterOptions()}</select></div><div id="library-results"></div>`}
function libraryLevelsHTML(){
  if(!['kanji','vocab'].includes(state.tab))return '';
  const kanji=state.tab==='kanji';
  return `<div class="level-filters" aria-label="${kanji?'Kanji':'Vocabulary'} levels">${[['all',kanji?'All kanji':'All words'],...[5,4,3,2,1].map(n=>['n'+n,'N'+n])].map(([value,label])=>`<button class="${state.filter===value?'active':''}" data-library-level="${value}" aria-pressed="${state.filter===value}">${label}</button>`).join('')}</div>`;
}
function filterOptions(){if(state.tab==='kanji')return `<option value="all">All kanji</option>${[5,4,3,2,1].map(n=>`<option value="n${n}" ${state.filter==='n'+n?'selected':''}>Estimated JLPT N${n}</option>`).join('')}${[1,2,3,4,5,6,8].map(n=>`<option value="g${n}" ${state.filter==='g'+n?'selected':''}>${n===8?'Secondary school':'School grade '+n}</option>`).join('')}<option value="studied" ${state.filter==='studied'?'selected':''}>Practiced items</option>`;if(state.tab==='vocab')return `<option value="all" ${state.filter==='all'?'selected':''}>All vocabulary</option><optgroup label="Estimated JLPT level">${[5,4,3,2,1].map(n=>`<option value="n${n}" ${state.filter==='n'+n?'selected':''}>N${n} · ${filterVocabulary(data.vocab,'n'+n).length.toLocaleString()} words</option>`).join('')}</optgroup><option value="core" ${state.filter==='core'?'selected':''}>Original 127 beginner words</option><optgroup label="Beginner topics">${[...new Set(data.vocab.filter(k=>k.topic).map(k=>k.topic))].map(t=>`<option value="${esc(t)}" ${state.filter===t?'selected':''}>${esc(t)}</option>`).join('')}</optgroup>`;return '<option value="all">All items</option>'}
function libraryItems(){if(state.tab==='vocab')return filterVocabulary(data.vocab,state.filter,state.search);let list=state.tab==='kanji'?data.kanji:state.tab==='vocab'?data.vocab:state.tab==='sentences'?data.sentences:data.kana.filter(k=>k.kind===state.tab);const f=state.filter;if(f!=='all'){if(f==='studied'){const learned=learnedIds();list=list.filter(k=>learned.has(k.id))}else if(state.tab==='kanji')list=list.filter(k=>f[0]==='n'?k.jlpt===Number(f.slice(1)):k.grade===Number(f.slice(1)));else if(state.tab==='vocab')list=list.filter(k=>k.topic===f)}const q=state.search.trim().toLowerCase();if(q)list=list.filter(k=>[k.char,k.reading,k.roman,...k.meanings,...k.on,...k.kun].filter(Boolean).some(t=>t.toLowerCase().includes(q)));return list}
function renderLibraryResults(){const list=libraryItems(),size=state.tab==='kanji'?96:state.tab==='sentences'?20:48,total=Math.ceil(list.length/size);state.page=Math.min(state.page,Math.max(0,total-1));const page=list.slice(state.page*size,(state.page+1)*size),known=learnedIds(),tiles=['kanji','hiragana','katakana'].includes(state.tab);$('#library-results').innerHTML=`<div class="count-label">${list.length.toLocaleString()} ${state.tab==='kanji'?'kanji':'items'}${['kanji','vocab'].includes(state.tab)?' · JLPT groupings are unofficial study estimates.':''}</div>${page.length?`<div class="${tiles?'library-grid':'vocab-grid'+(state.tab==='sentences'?' sentence-list':'')}">${page.map(k=>`<button class="${tiles?'char-tile':'word-tile'}" data-detail="${esc(k.id)}">${known.has(k.id)?'<span class="dot" title="Practiced"></span>':''}<span class="jp" lang="ja">${esc(k.char)}</span>${!tiles?`<span class="reading" lang="ja">${esc(k.reading)}</span>`:''}<small>${esc(mainMeaning(k))}</small>${k.kind==='vocab'?`<span class="vocab-level">${k.jlpt?'Est. N'+k.jlpt:'Beginner extra'}</span>`:''}</button>`).join('')}</div>`:'<div class="empty">No matches. Try another character, reading, or meaning.</div>'}${total>1?`<div class="pagination"><button class="secondary" data-page="-1" ${state.page===0?'disabled':''}>Previous</button><span>${state.page+1} of ${total}</span><button class="secondary" data-page="1" ${state.page===total-1?'disabled':''}>Next</button></div>`:''}`}
function reviewView(){
  const due=dueCards();
  return `${pageHeading('Daily reviews','Review times are based on your practice ratings.')}<section class="study-actions"><div><h2>${due.length} reviews due</h2><p>${due.length?'Items are listed by their next review time.':'Study new material to add it to your review schedule.'}</p></div><button class="primary" data-action="${due.length?'start-review':'start-lesson'}">${due.length?'Start daily review':'Start a lesson'} ${icon('arrow')}</button></section>
    ${due.length?`<section class="collection-section"><div class="section-title"><h2>Ready to review</h2><span class="small muted">Earliest due first</span></div><div class="panel recent-list">${due.slice(0,30).map(([key,c])=>{const item=items.get(key.split(':').slice(1).join(':'));return `<div class="recent-row"><span class="jp" lang="ja">${esc(item.char)}</span><span>${esc(mainMeaning(item))}<br><span class="small muted">${modeNames[key.split(':')[0]]}</span></span><small>${c.reps?'Learning':'Relearning'}</small></div>`}).join('')}</div></section>`:''}
    <section class="collection-section"><div class="section-title"><h2>Additional practice</h2></div>${modesHTML()}</section>`;
}
function skillProgressHTML(){
  const level=Number(state.progressLevel)||5,group=progressByLevel(profile()).find(g=>g.level===level);
  return `<section class="panel level-progress"><h2>Progress by level & skill</h2><p class="small muted">Skill breakdown tracks answers from this update onward. Older activity and test scores are retained. Accuracy uses your last 10 answers; trends compare them with the previous 10.</p><div class="level-filters" aria-label="Progress level">${[5,4,3,2,1].map(n=>`<button data-progress-level="${n}" aria-pressed="${n===level}" class="${n===level?'active':''}">N${n}</button>`).join('')}</div><div class="skill-progress-grid">${group.skills.map(g=>`<article class="skill-progress-card"><h3>${esc(g.label)}</h3><p class="skill-accuracy">${g.accuracy===null?'—':g.accuracy+'%'}<span>recent accuracy</span></p><p>${g.targets} distinct ${g.skill==='conjugation'?'word/forms':g.skill==='reading'?'reading questions':'items'} practiced · ${g.answered} answers</p><p class="small muted">${g.trend===null?'Answer more questions to establish a trend.':g.trend===0?'Unchanged from the previous 10 answers.':`${g.trend>0?'+':''}${g.trend} percentage points from the previous 10.`}</p><p class="small muted">Recent completed scores: ${g.scores.length?g.scores.map(n=>n+'%').join(' → '):'No level-specific scores yet.'}</p></article>`).join('')}</div></section>`;
}
function progressView(){const history=profile().history,learned=learnedIds(),days=new Map();[...history,...(profile().attempts||[]).filter(a=>a.origin!=='practice')].forEach(h=>days.set(localDay(h.at),(days.get(localDay(h.at))||0)+1));const start=new Date();start.setDate(start.getDate()-55);return `${pageHeading('Progress','Your study activity and review history.')}${statsHTML()}${skillProgressHTML()}<div class="two-col"><section class="panel"><div class="section-title"><div><h2>Study activity</h2><p>Practice activities over the last eight weeks.</p></div>${icon('calendar')}</div><div class="activity">${Array.from({length:56},(_,i)=>{const day=new Date(start);day.setDate(day.getDate()+i);const date=localDay(day),n=days.get(date)||0;return `<div class="activity-cell" style="background:${n>15?'#315d4d':n>7?'#7d9d82':n?'#d3dfcc':'#eceee3'}" title="${date}: ${n} activities" aria-label="${date}: ${n} activities"></div>`}).join('')}</div><div class="legend">Less <i style="background:#eceee3"></i><i></i><i style="background:#7d9d82"></i><i></i> More</div><div class="progress-bars" style="margin-top:30px">${[['Kanji',data.kanji],['Hiragana',data.kana.filter(k=>k.kind==='hiragana')],['Katakana',data.kana.filter(k=>k.kind==='katakana')],['Vocabulary',data.vocab],['Sentences',data.sentences],['Grammar',data.grammar]].map(([name,list])=>{const n=list.filter(k=>learned.has(k.id)).length;return `<div class="bar-row"><span>${name}</span><div class="stat-line"><i style="width:${n/list.length*100}%"></i></div><small>${n}/${list.length}</small></div>`}).join('')}</div></section><section class="panel"><h2 style="font-size:17px">Established items</h2><p class="small muted">A character is established here after at least three successful reviews and an interval of 21 days.</p><div class="stat-number"><b>${mastered().size}</b><span>established items</span></div><div style="height:20px"></div><h3>Practice by skill</h3>${['flash','write','listen','context'].map(m=>`<div class="recent-row">${icon({flash:'cards',write:'pen',listen:'sound',context:'text'}[m])}<span>${modeNames[m]}</span><small>${history.filter(h=>h.key.startsWith(m+':')).length}</small></div>`).join('')}</section></div><section class="panel" style="margin-bottom:30px"><h2 style="font-size:17px">Recent practice</h2>${history.length?history.slice(-8).reverse().map(h=>{const k=items.get(h.key.split(':').slice(1).join(':'));return k?`<div class="recent-row"><span class="jp" lang="ja">${esc(k.char)}</span><span>${modeNames[h.key.split(':')[0]]} · ${['Again','','','Hard','Good','Easy'][h.rating]}</span><small>${new Date(h.at).toLocaleDateString('en',{month:'short',day:'numeric'})}</small></div>`:''}).join(''):'<p class="small muted">Your practice history will appear here after your first activity.</p>'}</section>`}
function settingsView(){return `${pageHeading('Settings & learners','Audio, practice goals, learner profiles, and backups.')}<div class="settings-grid"><section class="panel"><h2>Your study preferences</h2><div class="form-row"><label for="learner-name">Learner name</label><input class="input" id="learner-name" maxlength="60" value="${esc(profile().name)}"></div><div class="form-row"><label for="daily-goal">Daily practice goal</label><select id="daily-goal">${[5,10,15,20,30,50,100].map(n=>`<option value="${n}" ${n===profile().goal?'selected':''}>${n} activities per day</option>`).join('')}</select></div><div class="form-row"><label class="checkbox-label"><input id="lenient" type="checkbox" ${saved.lenient!==false?'checked':''}> Gentle stroke checking</label><p class="small">Allows more variation in your handwriting. Checks are practice guidance, rather than a calligraphy grade.</p></div><button class="primary" data-action="save-settings">Save preferences ${icon('check')}</button></section><section class="panel"><h2>Japanese audio</h2><p>Uses Japanese speech voices provided by your browser or device. No paid audio service is used.</p><div class="form-row"><label for="voice-select">Voice</label><select id="voice-select">${voiceOptions()}</select></div><div class="form-row"><label for="speech-speed">Speaking speed</label><select id="speech-speed">${[[.6,'Slow'],[.8,'Relaxed'],[1,'Natural']].map(([v,t])=>`<option value="${v}" ${Number(saved.speed)===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="voice-notice">${voices.length?'':'<div class="notice">No Japanese voice was found. Add a Japanese text-to-speech voice in your device’s language settings, then reopen this app. Listening exercises need a Japanese voice; some device voices also need internet.</div>'}</div><div class="button-row"><button class="secondary" data-action="test-audio" ${!voices.length?'disabled':''}>${icon('sound')} Test voice</button><button class="primary" data-action="save-voice">Save audio settings</button></div></section><section class="panel"><h2>Learners on this device</h2><p>Each participant has their own reviews and progress. Profiles stay in this browser.</p><div class="profile-list">${saved.profiles.map(p=>`<button class="profile-option ${p.id===saved.active?'active':''}" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)}<span class="muted">${p.id===saved.active?'Active':p.history.length+' activities'}</span></button>`).join('')}</div><div class="inline-form" style="margin-top:16px"><input class="input" id="new-learner" maxlength="60" placeholder="New learner’s name" aria-label="New learner name"><button class="secondary" data-action="add-profile">Add learner</button></div></section><section class="panel"><h2>Keep your progress safe</h2><p>Export a backup regularly, and before changing devices or clearing browser data. Importing a backup adds profiles or replaces profiles with the same ID.</p><div class="button-row"><button class="secondary" data-action="export">${icon('download')} Export all learners</button><button class="secondary" data-action="import">${icon('upload')} Import backup</button></div><input type="file" id="backup-input" accept="application/json,.json" hidden><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Install & use offline</h3><p>After your first complete visit, the app and bundled lessons are cached for offline use. On supported browsers, use “Install app” or “Add to Home Screen.”</p><div class="button-row">${installPrompt?'<button class="secondary" data-action="install">Install app</button>':''}<button class="secondary" data-action="check-offline">Check offline readiness</button><a class="secondary" href="./data/kanji.json" download="kanji-path-kanji.json">Download kanji data</a></div></section><section class="panel settings-span"><h2>Built to help you learn</h2><p>Kanji Path is an independent study app with no paid API calls. Built-in content includes 2,136 kanji, 92 basic kana, ${data.vocab.length.toLocaleString()} vocabulary items with N5–N1 collections, 40 original practice sentences, and ${data.grammar.length} grammar lessons with formation rules and usage examples. JLPT labels are unofficial study estimates.</p><button class="text-link" data-action="sources">Sources, licences & how it works ${icon('arrow')}</button></section></div><div style="height:30px"></div>`}

function moreView(){
  return `${pageHeading('More','Study tools, progress, and settings.')}<div class="more-list">${[
    ['grammar','text','Grammar lessons','N5–N1 patterns and sentence examples'],['mistakes','book','Mistake notebook','Review incorrect answers'],['progress','chart','Progress','Study activity and established items'],['settings','settings','Settings & learners','Audio, goals, learner profiles, and backups']
  ].map(([route,glyph,title,description])=>`<button class="more-row" data-nav="${route}">${icon(glyph)}<span><strong>${title}</strong><small>${description}</small></span>${icon('chevron')}</button>`).join('')}<button class="more-row" data-action="sources">${icon('help')}<span><strong>Data & credits</strong><small>Sources, licences, and learning methods</small></span>${icon('chevron')}</button></div>`;
}

const tests=createTestPage({getProfile:profile,getItems:()=>[...items.values()],getMaterials:()=>({classes:data.conjugation.classes,reading:data.reading,strokes:data.strokes}),recordReview:(mode,item,correct)=>record(mode,item,correct?4:0,false,false),speak,stopSpeech,hasVoice:()=>voices.length>0,esc,jp,icon,pageHeading,persist,render,navigate:nav});
const learning=createLearningPages({getProfile:profile,getItems:()=>[...items.values()],getGrammar:()=>data.grammar,esc,jp,icon,pageHeading,modal,head,examplesHTML,record,persist,render,navigate:nav,practiceMistakes:()=>tests.openMistakes(),practiceSkill:(id,skill)=>{const item=items.get(id);if(!item)return;if(['writing','context','recall'].includes(skill)){startSession([item],{writing:'write',context:'context',recall:'flash'}[skill],1);if(session)session.mistakeSkill=skill}else if(!tests.openMistakes(id,skill))toast('This exercise needs a Japanese voice or its original sentence. Check Settings, or review the item.');}});
const views={more:moreView,grammar:()=>learning.grammarView(),mistakes:()=>learning.mistakesView(),test:()=>tests.view(),home:homeView,learn:learnView,library:libraryView,review:reviewView,progress:progressView,settings:settingsView};
function openCourse(id){session=null;const c=courses.find(c=>c.id===id);if(!c)return;modal(`${head(c.title,c.level)}<div class="modal-body"><p class="muted">${c.subtitle} ${c.items.length} items are included. Each lesson contains up to five new items.</p><div class="course-detail-tiles">${c.items.slice(0,24).map(k=>`<span lang="ja">${esc(k.kind==='vocab'?k.char.slice(0,3):k.kind==='sentence'?k.target:k.char)}</span>`).join('')}${c.items.length>24?'<span>…</span>':''}</div><div class="notice green">${c.id==='sentences'?'Read a sentence, use the reading hint, then choose the missing word.':c.id.startsWith('vocab')?'Explore readings and meanings, listen, then recall with flashcards. Vocabulary practice focuses on words and meanings, without handwriting.':'A guided lesson takes you through reading, listening, writing, and recall. You can also choose one skill to practice.'}</div><div class="button-row"><button class="primary" data-start-course="${c.id}">Begin ${c.id==='sentences'?'sentence practice':'guided lesson'} ${icon('arrow')}</button><button class="secondary" data-browse-course="${c.id}">Browse items</button></div>${c.id!=='sentences'?`<div class="button-row" style="margin-top:15px">${['flash','write','listen'].filter(m=>m!=='write'||c.items.some(k=>canWrite(k,data.strokes))).map(m=>`<button class="ghost" data-course-mode="${c.id}|${m}">${icon({flash:'cards',write:'pen',listen:'sound'}[m])}${modeNames[m]}</button>`).join('')}</div>`:''}</div>`)}
function openPractice(mode){session=null;const available=mode==='context'?courses.filter(c=>c.id==='sentences'):mode==='write'?courses.filter(c=>c.items.some(k=>canWrite(k,data.strokes))):courses.filter(c=>c.id!=='sentences');modal(`${head(modeNames[mode],'Choose a built-in collection')}<div class="modal-body"><div class="form-row"><label for="practice-collection">Collection</label><select id="practice-collection">${available.map(c=>`<option value="${c.id}">${c.title} · ${c.items.length} items</option>`).join('')}</select></div><div class="form-row"><label for="practice-size">Session length</label><select id="practice-size"><option value="5">5 items · a small step</option><option value="10">10 items · a focused session</option><option value="20">20 items · keep growing</option></select></div>${mode==='listen'&&!voices.length?'<div class="notice">A Japanese voice is needed for listening. Add one in your device’s language settings, or explore reading and writing first.</div>':''}<p class="small muted">New items come first. Practiced items return when they are due.</p><button class="primary" data-begin-practice="${mode}" ${mode==='listen'&&!voices.length?'disabled':''}>Start practice ${icon('arrow')}</button></div>`)}
function examplesHTML(k,collapsible=false){
 if(!['vocab','grammar'].includes(k.kind))return '';
 const examples=k.examples||[];
 const content=examples.length?examples.map((example,i)=>`<article class="usage-sentence"><p class="usage-japanese" lang="ja">${furiganaTokens(example.furigana||example.ja).map(t=>t.reading?`<ruby>${esc(t.text)}<rt>${esc(t.reading)}</rt></ruby>`:esc(t.text)).join('')}</p>${example.reading?`<p class="usage-reading" lang="ja">${esc(example.reading)}</p>`:''}<p class="usage-translation">${esc(example.en)}</p><div class="usage-actions"><button class="text-link" data-usage-speak="${esc(k.id)}|${i}" ${!voices.length?'disabled':''} aria-label="Listen to example sentence ${i+1}">${icon('sound')} Listen to sentence</button>${Number.isInteger(example.tatoeba_id)?`<a href="https://tatoeba.org/sentences/show/${example.tatoeba_id}" target="_blank" rel="noopener" class="usage-source">Tatoeba contributors · CC BY 2.0 FR ↗</a>`:k.kind==='grammar'?'<span class="usage-source">OpenJLPT contributors · CC BY-SA 4.0</span>':'<span class="usage-source">Kanji Path · CC0</span>'}</div></article>`).join(''):'<p class="small muted">No sentence example is bundled for this word and reading yet.</p>';
 return collapsible?`<details class="usage-examples"><summary>See sentence examples${examples.length?' ('+examples.length+')':''}</summary>${content}</details>`:`<section class="usage-examples"><h3>Examples in sentences</h3>${content}</section>`;
}
function openDetail(id,from=null){
 const k=items.get(id);if(!k)return;if(k.kind==='passage'){tests.openMistakes(id,'comprehension:0');return}session=null;if(k.kind==='grammar'){learning.openGrammar(id);return}
 const paths=canWrite(k,data.strokes)?data.strokes[k.char]:null,isKanji=!k.kind;
 const related=isKanji?data.vocab.filter(v=>v.char.includes(k.char)).slice(0,5):[];
 const parent=from?items.get(from):null;
 modal(`${head(k.kind==='sentence'?'Sentence explorer':k.kind==='vocab'?'Word explorer':'Character explorer')}<div class="modal-body">${parent?`<button class="text-link detail-back" data-detail="${esc(parent.id)}">← Back to ${esc(parent.char)}</button>`:''}<div class="detail-top ${k.kind==='vocab'?'word-detail':''}" ${k.kind==='sentence'?'style="display:block"':''}><div class="detail-glyph" lang="ja" ${k.char.length>2?'style="font-size:36px;padding:15px"':''}>${esc(k.char)}</div><div><h3 style="${k.kind==='sentence'?'margin-top:20px':''}">${esc(k.meanings.join('; '))}</h3>${k.reading?`<p lang="ja" class="muted">${esc(k.reading)}</p>`:''}${isKanji?`<span class="tag">${k.strokes} strokes</span><span class="tag">${k.grade===8?'Secondary school':'Grade '+k.grade}</span>${k.jlpt?`<span class="tag">Est. N${k.jlpt}</span>`:''}`:`<span class="tag">${esc(k.topic||k.kind)}</span>${k.kind==='vocab'&&k.jlpt?`<span class="tag">Estimated JLPT N${k.jlpt}</span>`:''}`}</div></div>${isKanji?`<div class="readings"><div><label>On’yomi · sound readings</label><p lang="ja">${esc(k.on.join('、')||'—')}</p></div><div><label>Kun’yomi · native readings</label><p lang="ja">${esc(k.kun.join('、')||'—')}</p></div></div><p class="small muted">Dots in readings separate the kanji reading from its following kana. A character can have several readings depending on the word.</p>`:''}<div class="button-row"><button class="secondary" data-speak="${esc(id)}" ${!voices.length?'disabled':''}>${icon('sound')} Hear ${isKanji?'a reading':'pronunciation'}</button>${paths?`<button class="secondary" data-detail-animate="${esc(id)}">${icon('play')} Stroke order</button>`:''}<button class="primary" data-single="${esc(id)}" data-mode="${paths?'write':k.kind==='sentence'?'context':'flash'}">${icon(paths?'pen':'cards')} Practice</button></div>${!voices.length?'<p class="small muted" style="margin-top:12px">Audio needs a Japanese voice on your device. See Settings for setup.</p>':''}<div id="detail-animation"></div>${examplesHTML(k)}${related.length?`<h3 style="margin-top:27px">In everyday words</h3><p class="small muted">Choose a word to see its meaning and sentence examples.</p><div class="detail-examples">${related.map(v=>`<div class="example"><button class="example-link" data-detail="${esc(v.id)}" data-from-detail="${esc(k.id)}" aria-label="See sentence examples for ${esc(v.char)}"><span class="jp" lang="ja">${esc(v.char)}</span><span class="reading" lang="ja">${esc(v.reading)}</span><span class="meaning">${esc(mainMeaning(v))}</span>${icon('chevron')}</button><button data-speak="${esc(v.id)}" aria-label="Play ${esc(v.char)}" ${!voices.length?'disabled':''}>${icon('sound')}</button></div>`).join('')}</div>`:''}</div>`);
}
function selectQueue(list,mode,count){if(mode==='write')list=list.filter(k=>canWrite(k,data.strokes));const cards=profile().cards;const newItems=list.filter(k=>!cards[`${mode}:${k.id}`]);const due=list.filter(k=>cards[`${mode}:${k.id}`]?.due<=Date.now()).sort((a,b)=>cards[`${mode}:${a.id}`].due-cards[`${mode}:${b.id}`].due);const future=shuffle(list.filter(k=>cards[`${mode}:${k.id}`]?.due>Date.now()));return [...newItems,...due,...future].slice(0,count)}
function startSession(list,mode='guided',count=5,review=false){if(mode==='listen'&&!voices.length){toast('Add a Japanese voice in your device settings to practice listening.');return}const effective=mode==='guided'?'flash':mode;const queue=review?list.filter(q=>q.mode!=='write'||canWrite(q.item,data.strokes)):selectQueue(list,effective,count).map(k=>({item:k,mode}));if(!queue.length){toast('No items available for this practice.');return}session={queue,index:0,step:0,revealed:false,choice:null,correct:null,completed:0,successes:0,started:Date.now(),review,played:false,written:false};renderSession()}
const current=()=>session?.queue[session.index];
function sessionStep(){const q=current();return q.mode==='guided'?lessonSteps(q.item,data.strokes)[session.step]:q.mode}
function renderSession(){if(!session)return;if(session.index>=session.queue.length){showResults();return}const q=current(),k=q.item,mode=sessionStep(),n=session.index+1;
 const steps=q.mode==='guided'?lessonSteps(k,data.strokes).map(s=>({explore:'Explore','guided-listen':'Listen',write:'Write',flash:'Recall'}[s])):[];
 const prefix=`${head(modeNames[q.mode],`${n} of ${session.queue.length} items${session.review?' · Daily review':''}`)}<div class="session-progress"><span style="width:${session.index/session.queue.length*100}%"></span></div>`;
 let body='';const glyphClass=k.kind==='sentence'?'sentence':k.char.length>1?'word':'';
 if(mode==='explore'){body=`<div class="session-body"><div class="session-steps">${steps.map((s,i)=>`<span class="${i===session.step?'active':''}">${i+1}. ${s}</span>`).join('')}</div><div class="step-label">MEET YOUR NEXT ${k.kind==='vocab'?'WORD':'CHARACTER'}</div><div class="study-glyph ${glyphClass}" lang="ja">${esc(k.char)}</div><h3>${esc(k.meanings.slice(0,3).join(' · '))}</h3><div class="study-reading" lang="ja">${esc(k.kind==='vocab'||k.kind?.includes('kana')?k.reading:[...k.on.slice(0,2),...k.kun.slice(0,2)].join(' / '))}</div><p class="study-sub">${k.kind?.includes('kana')?`Pronounced “${esc(k.roman)}”.`:k.kind==='vocab'?k.jlpt?`Vocabulary for estimated JLPT N${k.jlpt}.`:'A useful word for your everyday Japanese.':`${k.strokes} strokes · Notice the shape, then say a reading aloud.`}</p>${examplesHTML(k,true)}</div><div class="study-footer"><span class="small">Read the meaning and readings before continuing.</span><button class="primary" data-action="next-step">Listen next ${icon('arrow')}</button></div>`}
 else if(mode==='guided-listen'){body=`<div class="session-body"><div class="session-steps">${steps.map((s,i)=>`<span class="${i===session.step?'active':''}">${i+1}. ${s}</span>`).join('')}</div><div class="step-label">LISTEN & SAY IT ALOUD</div><div class="study-glyph ${glyphClass}" lang="ja">${esc(k.char)}</div><button class="audio-circle" data-action="session-speak" aria-label="Play Japanese pronunciation" ${!voices.length?'disabled':''}>${icon('sound')}</button><div class="study-reading" lang="ja">${esc(itemReading(k))}</div><p class="study-sub">${voices.length?'Tap to listen, then try repeating what you hear.':'No Japanese voice is available. You can continue, then add a voice in Settings.'}</p></div><div class="study-footer"><span class="small">${voices.length?'Listen as many times as you like.':'Audio is optional in a guided lesson.'}</span><button class="primary" data-action="next-step">${canWrite(k,data.strokes)?'Try writing':'Try recalling'} ${icon('arrow')}</button></div>`}
 else if(mode==='write'){body=`<div class="session-body">${steps.length?`<div class="session-steps">${steps.map((s,i)=>`<span class="${i===session.step?'active':''}">${i+1}. ${s}</span>`).join('')}</div>`:''}<div class="step-label">WRITE IT, ONE STROKE AT A TIME</div><h3>${esc(mainMeaning(k))}</h3><p class="study-sub" style="margin-bottom:8px">${jp(itemReading(k))} · Use your finger, mouse, or pen.</p><div class="drawing-wrap" id="drawing-host"></div><div class="stroke-counter" id="stroke-counter"></div><div class="writing-feedback" id="writing-feedback" role="status">Begin near the large dot and follow the orange arrow.</div><div class="writing-tools"><button data-action="writing-hint">Show next stroke</button><button data-action="writing-guide">Hide outline</button><button data-action="writing-reset">Start again</button><button data-action="writing-animate">Watch stroke order</button></div><div id="writing-ratings"></div></div><div class="study-footer"><span class="small" id="writing-footer">Follow the Japanese stroke order.</span>${q.mode==='guided'?'<button class="primary" id="write-next" data-action="next-step" disabled>Try recalling '+icon('arrow')+'</button>':'<button class="ghost" data-action="skip-item">Skip this item</button>'}</div>`}
 else if(mode==='flash'){body=`<div class="session-body">${steps.length?`<div class="session-steps">${steps.map((s,i)=>`<span class="${i===session.step?'active':''}">${i+1}. ${s}</span>`).join('')}</div>`:''}<div class="step-label">${session.revealed?'Rate your recall':'Recall the meaning'}</div><button class="flash" data-action="reveal" aria-label="${session.revealed?'Answer revealed':'Reveal answer'}"><span class="study-glyph ${glyphClass}" lang="ja">${esc(k.char)}</span>${session.revealed?`<span class="study-reading" lang="ja">${esc(itemReading(k))}</span><span class="meaning">${esc(k.meanings.slice(0,3).join(' · '))}</span>`:'<span class="small muted">Think of the meaning and a reading. Tap to reveal.</span>'}</button>${session.revealed?grammarRecallHTML(k)+examplesHTML(k,true):''}${session.revealed?ratingsHTML('flash',k.id):'<button class="primary" data-action="reveal" style="margin-top:22px">Reveal answer '+icon('arrow')+'</button>'}</div><div class="study-footer"><span class="small">${session.revealed?'Your rating sets the next review time.':'Think of the answer before revealing it.'}</span><button class="ghost" data-action="skip-item">Skip</button></div>`}
 else if(mode==='listen'||mode==='context'){if(!session.options){const pool=mode==='context'?data.sentences:k.kind==='vocab'?(k.jlpt?filterVocabulary(data.vocab,'n'+k.jlpt):data.vocab):k.kind?.includes('kana')?data.kana.filter(x=>x.kind===k.kind):data.kanji;const others=shuffle(pool.filter(x=>x.id!==k.id&&(mode==='context'?x.target!==k.target:itemReading(x)!==itemReading(k)&&mainMeaning(x)!==mainMeaning(k))));const opts=[k];const used=new Set([mode==='context'?k.target:k.char]);for(const other of others){const text=mode==='context'?other.target:other.char;if(!used.has(text)){opts.push(other);used.add(text)}if(opts.length===4)break}session.options=shuffle(opts)}
 const reveal=session.choice!==null;body=`<div class="session-body"><div class="step-label">${mode==='listen'?'LISTEN CLOSELY. WHICH ONE DID YOU HEAR?':'COMPLETE THE SENTENCE'}</div>${mode==='listen'?`<button class="audio-circle" data-action="session-speak" aria-label="Play the listening question" ${!voices.length?'disabled':''}>${icon('sound')}</button><p class="study-sub">${voices.length?'Tap to hear the Japanese reading.':'A Japanese voice is needed. Set one up in Settings.'}</p>${reveal?`<div class="study-glyph word" lang="ja">${esc(k.char)}</div><div class="study-reading" lang="ja">${esc(itemReading(k))}</div>`:''}`:`<div class="cloze" lang="ja">${esc(k.char).replace(esc(k.target),`<ruby><span class="blank">${reveal?esc(k.target):'？'}</span><rt>${esc(k.targetReading)}</rt></ruby>`)}</div><p class="study-sub">${esc(k.meanings[0])}</p>${reveal?`<p class="small muted" lang="ja">${esc(k.reading)}</p><button class="secondary" data-action="session-speak" ${!voices.length?'disabled':''}>${icon('sound')} Hear sentence</button>`:''}`}
 <div class="options">${session.options.map(o=>`<button class="option ${reveal?(o.id===k.id?'correct':o.id===session.choice?'wrong':''):''}" data-choice="${esc(o.id)}" ${reveal?'disabled':''}><span lang="ja">${esc(mode==='context'?o.target:o.char)}</span>${mode==='listen'&&!o.kind?.includes('kana')?`<span class="small muted" style="display:block;margin-top:5px">${esc(mainMeaning(o))}</span>`:''}</button>`).join('')}</div>${reveal?`<div class="writing-feedback ${session.correct?'success':'error'}">${session.correct?'Correct.':`Keep going. The answer is ${esc(mode==='context'?k.target:k.char)}.`}</div>`:''}</div><div class="study-footer"><span class="small">${mode==='context'?'The small reading is your hint.':'Replay at your own pace.'}</span>${reveal?'<button class="primary" data-action="choice-next">Continue '+icon('arrow')+'</button>':'<button class="ghost" data-action="skip-item">Skip</button>'}</div>`}
 modal(prefix+body);if(mode==='write')initWriting(k);
}
function grammarRecallHTML(k){return k.kind==='grammar'?`<div class="grammar-formation"><h3>How to form it</h3><p>${esc(k.formation)}</p>${k.notes?`<p class="small">${esc(k.notes)}</p>`:''}</div>`:''}
function ratingsHTML(mode,id){const card=profile().cards[`${mode}:${id}`];return `<div class="ratings">${[[0,'Again'],[3,'Hard'],[4,'Good'],[5,'Easy']].map(([n,t])=>{const next=schedule(card,n);return `<button class="rating" data-rating="${n}">${t}<small>${n===0?'10 minutes':next.interval===1?'1 day':next.interval+' days'}</small></button>`}).join('')}</div>`}
function record(mode,k,rating,trackMistake=true,trackProgress=true,skillOverride=null){const key=`${mode}:${k.id}`,p=profile(),now=Date.now();p.cards[key]=schedule(p.cards[key],rating,now);const skill=skillOverride||{flash:'meaning',write:'writing',listen:'listening',context:'cloze'}[mode]||'recall';if(trackMistake)updateMistake(p,k.id,rating!==0,'practice',now,skill);if(trackProgress)recordAttempt(p,{itemId:k.id,skill,category:k.kind==='vocab'?'vocab':k.kind==='sentence'?'sentences':k.kind==='grammar'?'grammar':['hiragana','katakana'].includes(k.kind)?'kana':'kanji',level:k.jlpt,correct:rating!==0,origin:'practice'},now);p.history.push({key,rating,at:now});if(p.history.length>10000)p.history=p.history.slice(-10000);persist()}
function rateAndNext(rating){const q=current();if(!q)return;const m=q.mode==='guided'?'flash':q.mode;record(m,q.item,rating,true,true,session.mistakeSkill);if(q.mode==='guided'){if(session.written&&canWrite(q.item,data.strokes))record('write',q.item,4,false);if(session.played)record('listen',q.item,4,false,false)}session.completed++;if(rating>=3)session.successes++;nextItem()}
function nextItem(){if(!session)return;stopSpeech();session.index++;session.step=0;session.revealed=false;session.choice=null;session.correct=null;session.options=null;session.played=false;session.written=false;renderSession()}
function showResults(){
  const result=session;
  modal(`${head('Session complete','Practice results')}<div class="session-body"><div class="result-icon">${icon('check')}</div><h3>Progress saved</h3><p class="muted">Saved for ${esc(profile().name)}.</p><div class="result-stats"><div><b>${result.completed}</b><small>items practiced</small></div><div><b>${result.successes}</b><small>remembered</small></div><div><b>${Math.max(1,Math.round((Date.now()-result.started)/60000))}</b><small>minutes</small></div></div><div class="notice">${dueCards().length?`${dueCards().length} reviews are ready.`:'No reviews are currently due.'}</div><button class="primary" data-action="finish-session">Close results ${icon('check')}</button></div>`);
}
function resumeSession(){const confirmation=$('#session-exit');if(confirmation.open)confirmation.close()}
function exitSession(){if(!session)return;const confirmation=$('#session-exit');if(!confirmation.open)confirmation.showModal()}
$('#session-exit').addEventListener('cancel',e=>{e.preventDefault();resumeSession()});
function boardMarkup(paths,{outline=true}={}){return `<svg class="drawing-board" viewBox="0 0 109 109" role="img" aria-label="Japanese character writing area with stroke direction arrows"><path class="gridline" d="M54.5 0V109M0 54.5H109M0 0L109 109M109 0L0 109"/><g id="outline-group" ${!outline?'style="display:none"':''}>${paths.map(d=>`<path class="outline" d="${esc(d)}"/>`).join('')}</g><g id="accepted-group"></g><g id="hint-group"></g><path class="userstroke" id="user-stroke" d=""/></svg>`}
function pathPoints(d){const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);const n=path.getTotalLength();return Array.from({length:40},(_,i)=>{const p=path.getPointAtLength(n*i/39);return [p.x,p.y]})}
function initWriting(k){if(!canWrite(k,data.strokes))return;const paths=data.strokes[k.char]||[];$('#drawing-host').innerHTML=boardMarkup(paths);writer={paths,index:0,points:[],drawing:false,outline:true,mistakes:0,complete:false,busy:false};const svg=$('.drawing-board');
 const toPoint=e=>{const r=svg.getBoundingClientRect();return [(e.clientX-r.left)*109/r.width,(e.clientY-r.top)*109/r.height]};
 svg.addEventListener('pointerdown',e=>{if(!writer||writer.complete||writer.busy||writer.drawing||e.button>0)return;e.preventDefault();svg.setPointerCapture(e.pointerId);writer.drawing=true;writer.pointer=e.pointerId;writer.points=[toPoint(e)];$('#user-stroke').setAttribute('d',`M${writer.points[0].join(' ')}`)});
 svg.addEventListener('pointermove',e=>{if(!writer?.drawing||e.pointerId!==writer.pointer)return;e.preventDefault();const p=toPoint(e);writer.points.push(p);$('#user-stroke').setAttribute('d',writer.points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '))});
 svg.addEventListener('pointerup',e=>{if(!writer?.drawing||e.pointerId!==writer.pointer)return;writer.points.push(toPoint(e));writer.drawing=false;svg.releasePointerCapture(e.pointerId);finishStroke()});
 svg.addEventListener('pointercancel',()=>{if(writer){writer.drawing=false;writer.points=[]}$('#user-stroke')?.setAttribute('d','')});updateWriting();
}
function directionMarkup(points,fraction=.25){const a=strokeArrow(points,fraction);return a?`<g class="stroke-direction" aria-hidden="true" transform="translate(${a.x} ${a.y}) rotate(${a.angle})"><path d="M-5 0H0M-2.5-2.4L0 0L-2.5 2.4"/></g>`:''}
function updateWriting(){
 if(!writer)return;const w=writer;
 $('#accepted-group').innerHTML=w.paths.slice(0,w.index).map(d=>`<path class="accepted" d="${esc(d)}"/>`).join('');
 $('#hint-group').innerHTML=w.outline&&w.index<w.paths.length?`<path class="hint" d="${esc(w.paths[w.index])}"/>${(()=>{const points=pathPoints(w.paths[w.index]),p=points[0];return `<circle class="start-dot" cx="${p[0]}" cy="${p[1]}" r="4"/>${directionMarkup(points)}`})()}`:'';
 $('#stroke-counter').textContent=`${w.index} / ${w.paths.length} strokes completed`;
 if(w.complete){$('#writing-feedback').className='writing-feedback success';$('#writing-feedback').textContent='Well done. You wrote the whole character.';if(session){session.written=true;if(current().mode==='guided')$('#write-next').disabled=false;else $('#writing-ratings').innerHTML=ratingsHTML('write',current().item.id)}}
}
function finishStroke(){if(!writer)return;const w=writer,result=checkStroke(w.points,pathPoints(w.paths[w.index]),saved.lenient!==false);$('#user-stroke').setAttribute('d','');if(result.ok){w.index++;w.mistakes=0;w.complete=w.index===w.paths.length;$('#writing-feedback').className='writing-feedback success';$('#writing-feedback').textContent='Good stroke. Keep going.';updateWriting()}else{w.mistakes++;$('#writing-feedback').className='writing-feedback error';$('#writing-feedback').textContent=result.message;if(w.mistakes>=3)animateWritingStroke()}}
async function animatePaths(paths,group){
 const token=++animToken;
 for(const d of paths){
  if(token!==animToken||!group.isConnected)return;
  const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',d);p.setAttribute('class','accepted');
  const len=p.getTotalLength(),points=pathPoints(d);p.style.strokeDasharray=len;p.style.strokeDashoffset=len;group.append(p);
  const arrows=document.createElementNS('http://www.w3.org/2000/svg','g'),startDot=`<circle class="start-dot" cx="${points[0][0]}" cy="${points[0][1]}" r="4"/>`;group.append(arrows);
  const animation=p.animate([{strokeDashoffset:len},{strokeDashoffset:0}],{duration:550,fill:'forwards'});
  const moveArrow=()=>{if(token!==animToken||!group.isConnected)return;arrows.innerHTML=startDot+directionMarkup(points,Math.min(1,Number(animation.currentTime||0)/550));if(animation.playState==='running')requestAnimationFrame(moveArrow)};moveArrow();
  await animation.finished.catch(()=>{});if(token!==animToken)return;
  arrows.innerHTML=startDot+directionMarkup(points);
  await new Promise(resolve=>setTimeout(resolve,100));
 }
 return token;
}
async function animateWritingStroke(){if(!writer||writer.complete||writer.busy)return;writer.busy=true;const w=writer,group=$('#hint-group');group.innerHTML='';await animatePaths([w.paths[w.index]],group);if(writer===w){w.busy=false;updateWriting()}}
async function animateWritingAll(){if(!writer||writer.busy)return;const w=writer;w.busy=true;const group=$('#accepted-group');group.innerHTML='';$('#hint-group').innerHTML='';await animatePaths(w.paths,group);if(writer===w){w.busy=false;updateWriting()}}
async function detailAnimate(id){const k=items.get(id);if(!canWrite(k,data.strokes))return;const paths=data.strokes[k.char];$('#detail-animation').innerHTML=`<p class="small muted">Start at each dot. The orange arrow follows the drawing direction.</p><div class="drawing-wrap">${boardMarkup(paths)}</div>`;await animatePaths(paths,$('#detail-animation #accepted-group'))}
function refreshVoices(){const previous=voices.map(v=>v.voiceURI).join('|');voices=window.speechSynthesis?window.speechSynthesis.getVoices().filter(v=>/^ja(?:-|_)/i.test(v.lang)||v.lang==='ja'):[];if($('#voice-select')){$('#voice-select').innerHTML=voiceOptions();if(voices.length)$('#voice-notice').innerHTML=''}if(voices.length&&$('#modal').open)$('#modal').querySelectorAll('[data-speak],[data-usage-speak]').forEach(b=>b.disabled=false);if(data.kanji&&state.view==='test'&&previous!==voices.map(v=>v.voiceURI).join('|'))tests.onVoicesChanged()}
function voiceOptions(){return voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${saved.voice===v.voiceURI?'selected':''}>${esc(v.name)}${v.localService?' · on device':' · online'}</option>`).join(''):'<option>No Japanese voice available</option>'}
function stopSpeech(){window.speechSynthesis?.cancel();document.querySelectorAll('.audio-circle').forEach(b=>b.classList.remove('speaking'))}
function speak(text,options={}){if(!voices.length){toast('No Japanese voice is installed. See Japanese audio in Settings.');return false}stopSpeech();const u=new SpeechSynthesisUtterance(text);u.voice=voices.find(v=>v.voiceURI===saved.voice)||voices[0];u.lang='ja-JP';u.rate=Number(options.rate)||Number(saved.speed)||.8;u.onstart=()=>document.querySelectorAll('.audio-circle').forEach(b=>b.classList.add('speaking'));u.onend=()=>{document.querySelectorAll('.audio-circle').forEach(b=>b.classList.remove('speaking'));if(session)session.played=true;options.onEnd?.()};u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('Audio could not play. Try another Japanese voice in Settings.');document.querySelectorAll('.audio-circle').forEach(b=>b.classList.remove('speaking'));options.onError?.()};window.speechSynthesis.speak(u);return true}
function profilesModal(){session=null;modal(`${head('Learner profiles','Separate progress for everyone on this device')}<div class="modal-body"><div class="profile-list">${saved.profiles.map(p=>`<button class="profile-option ${p.id===saved.active?'active':''}" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)}<span class="muted">${p.id===saved.active?'Active':p.history.length+' activities'}</span></button>`).join('')}</div><div class="inline-form" style="margin-top:20px"><input class="input" id="new-learner" maxlength="60" placeholder="New learner’s name" aria-label="New learner name"><button class="primary" data-action="add-profile">Add learner</button></div></div>`)}
function exportBackup(){const blob=new Blob([JSON.stringify({...saved,exported:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`kanji-path-backup-${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Backup exported. Keep it somewhere safe.')}
async function importBackup(file){if(!file)return;if(file.size>15*1024*1024){toast('This backup is too large. Choose a file under 15 MB.');return}try{const incoming=JSON.parse(await file.text()),profiles=validateBackup(incoming,new Set(items.keys()));const overlaps=profiles.filter(p=>saved.profiles.some(x=>x.id===p.id));if(overlaps.length){session=null;modal(`${head('Restore your progress')}<div class="modal-body"><p>This backup replaces the saved progress for ${overlaps.map(p=>esc(p.name)).join(', ')} and adds any new learners.</p><p class="small muted">Export your current backup first if you want to keep both versions.</p><div class="button-row"><button class="secondary" data-action="export">Export current progress</button><button class="primary" id="confirm-import">Restore backup</button><button class="ghost" data-action="close">Cancel</button></div></div>`);$('#confirm-import').onclick=()=>applyImport(profiles)}else applyImport(profiles)}catch(e){toast(e.message==='Unexpected token'?'Unable to read this backup.':e.message.startsWith('Invalid')||e.message.includes('Kanji Path')?e.message:'Unable to read this backup. Choose a Kanji Path JSON export.')}}
function applyImport(profiles){const map=new Map(saved.profiles.map(p=>[p.id,p]));profiles.forEach(p=>map.set(p.id,p));if(map.size>50){toast('A maximum of 50 learner profiles is supported.');return}saved.profiles=[...map.values()];persist();closeModal();toast('Backup restored. Progress restored.')}
function sourcesModal(){session=null;modal(`${head('Free tools. Shared knowledge.','Sources, licences & learning methods')}<div class="modal-body"><p class="small muted">Kanji Path is an independent learning app. It is not affiliated with Kanji Study. Your data is stored on this device, without an account or paid API.</p><ul class="source-list"><li><strong>Kanji meanings and readings:</strong> KANJIDIC / KANJIDIC2, copyright Jim Breen and the Electronic Dictionary Research and Development Group, via David Luz Gouveia’s kanji-data conversion. <a href="https://www.edrdg.org/wiki/index.php/KANJIDIC_Project" target="_blank" rel="noopener">KANJIDIC project</a> · <a href="https://www.edrdg.org/edrdg/licence.html" target="_blank" rel="noopener">CC BY-SA 4.0 and conditions</a>. The bundled dataset selects 2,136 Jōyō kanji and retains meanings, readings, school grade, stroke count, frequency, and estimated JLPT labels. WaniKani material is excluded.</li><li><strong>JSON conversion:</strong> <a href="https://github.com/davidluzgouveia/kanji-data" target="_blank" rel="noopener">David Luz Gouveia / kanji-data</a>, MIT. JLPT groupings from Jonathan Waller’s resources are unofficial estimates. They are not official exam syllabuses.</li><li><strong>Stroke data:</strong> <a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener">KanjiVG</a>, copyright Ulrich Apel and contributors, <a href="./data/KANJIVG-LICENSE.txt" target="_blank">CC BY-SA 3.0</a>. Stroke paths are extracted from the SVGs into a compact JSON mapping for 2,228 characters, preserving stroke order. <a href="./data/strokes.json" download>Download the adapted stroke data</a>.</li><li><strong>N5–N1 vocabulary:</strong> 7,811 graded entries from <a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener">OpenJLPT</a>, using Jonathan Waller’s JLPT lists and JMdict (EDRDG). Readings and English meanings are adapted into the app’s card format; matching original cards retain their IDs and glosses. Usage sentences and available furigana come from Tatoeba via OpenJLPT. Each sentence links to its Tatoeba contributors under <a href="https://creativecommons.org/licenses/by/2.0/fr/" target="_blank" rel="noopener">CC BY 2.0 FR</a>; original supplementary examples are CC0. The adapted vocabulary dataset is <a href="./data/OPENJLPT-LICENSE.txt" target="_blank">CC BY-SA 4.0</a>. <a href="./data/OPENJLPT-NOTICE.md" target="_blank">Upstream attribution</a> · <a href="./data/vocab-meta.json" target="_blank">Pinned snapshot & counts</a> · <a href="./data/vocab.json" download>Download adapted data</a>. Levels are unofficial estimates, not an official exam syllabus.</li><li><strong>N5–N1 grammar:</strong> 526 lessons from <a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener">OpenJLPT</a>, with original explanations, formation rules, notes, and examples. Field names and IDs are adapted; the dataset remains <a href="./data/OPENJLPT-LICENSE.txt" target="_blank">CC BY-SA 4.0</a>. <a href="./data/grammar-meta.json" target="_blank">Pinned revision & source hashes</a> · <a href="./data/grammar.json" download>Download adapted grammar</a>. Levels are unofficial estimates.</li><li><strong>Conjugation and graded reading:</strong> Conjugation classes for 1,981 vocabulary entries derive from the pinned OpenJLPT / JMdict snapshot under CC BY-SA 4.0. <a href="./data/conjugation.json" target="_blank">Mapping and source hashes</a>. Exercise logic is original app code. ${data.reading.length} original graded reading passages, glossaries, questions, explanations, and translations are provided by Kanji Path under CC0. <a href="./data/reading.json" download>Download reading material</a>. Reading levels are estimates. Dictation uses existing attributed sentence examples and the device’s Japanese voice.</li><li><strong>Original beginner learning material:</strong> 127 vocabulary entries and 40 original practice sentences assembled for this app; basic kana tables. Distributed under CC0. Sentence readings are whole-sentence guides; they do not encode pitch accent.</li><li><strong>Review scheduling:</strong> a local SM-2-style algorithm. Again returns in 10 minutes; successful reviews receive a growing interval based on your rating. Reading, writing, listening, and context are tracked separately.</li><li><strong>Handwriting:</strong> a geometric comparison against KanjiVG stroke paths checks position, direction, and shape in the expected order. It is a learning aid, not general handwriting recognition or a perfect assessment.</li><li><strong>Listening:</strong> your device’s Japanese text-to-speech voice. Availability, pronunciation, and offline playback depend on your device.</li></ul><p class="small muted">Data snapshot bundled on 21 October 2026. Developers can refresh character data with scripts/build-data.py, vocabulary with scripts/build-vocab.py, and grammar with scripts/build-grammar.py. Dictionary-derived data retains its upstream licence; app source code is provided under MIT.</p></div>`)}
async function checkOffline(){if(!('serviceWorker'in navigator)){toast('Offline installation is not supported by this browser.');return}const reg=await navigator.serviceWorker.getRegistration();if(!reg?.active){toast('Offline setup is still starting. Keep this tab open, then check again.');return}const cache=await caches.open('kanji-path-v14');const keys=await cache.keys();toast(keys.length>=36?'App and all eight lesson datasets are saved for offline use. Audio depends on your device voice.':'Offline content is still being cached. Keep this tab open and check again.')}
